# Reference solution W4 (Python), MUTANT=FIXED_BACKOFF. Generated by references/build.py; do not edit.
# --- reference HTTP policy (shared by all Python reference solutions) --------
# Written from the criteria of draft Section IV-F, not from model output:
#  * every attempt is bounded as a whole (connect, headers and body) and every
#    call of the function by a deadline within its time limit (10 s if none);
#  * transient failures (429, 502-504, connection errors) are retried, at most
#    6 attempts, with capped exponential backoff and full jitter over
#    [100 ms, min(4 s, 0.5 s * 2^k)];
#  * Retry-After (delta-seconds or HTTP-date) is respected;
#  * a request that may have reached the server is repeated only if it is
#    idempotent or carries an idempotency key.
# MUTANT selects one deliberately broken variant (references/README.md).
import email.utils
import random
import threading
import time

import requests
import urllib3

MUTANT = "FIXED_BACKOFF"

CONNECT_TIMEOUT_S = 2.0
ATTEMPT_TIMEOUT_S = 3.0
BASE_DELAY_S = 0.5
MAX_DELAY_S = 4.0
MIN_DELAY_S = 0.1
MAX_ATTEMPTS = 6  # per logical call (TIGHT_LOOP removes this cap too)
MIN_ATTEMPT_S = 0.3  # no attempt starts with less time than this left (2 x typical latency)
RETRY_STATUSES = {429, 502, 503, 504}


class _GiveUp(Exception):
    """Retrying is pointless or would exceed the deadline."""


class _AttemptTimeout(Exception):
    pass


class Response:
    def __init__(self, status, headers, body):
        self.status, self.headers, self.body = status, headers, body

    def json(self):
        import json
        return json.loads(self.body)


def _sent_maybe(exc):
    """False if the request certainly did not reach the server (connection
    refused or connect timeout); True otherwise (it may have been processed)."""
    if isinstance(exc, requests.exceptions.ConnectTimeout):
        return False
    if isinstance(exc, requests.exceptions.ConnectionError):
        reason = getattr(exc.args[0], "reason", None) if exc.args else None
        if isinstance(reason, urllib3.exceptions.NewConnectionError):
            return False
    return True


def _retry_after_s(headers):
    v = headers.get("Retry-After")
    if v is None:
        return None
    v = v.strip()
    if v.isdigit():
        return float(v)
    try:
        return max(0.0, email.utils.parsedate_to_datetime(v).timestamp() - time.time())
    except (TypeError, ValueError):
        return None


def _one_attempt(method, url, timeout_s, sink=None, **kw):
    """One HTTP exchange bounded as a whole by timeout_s (requests' own timeouts
    bound single socket operations only, so a trickled body would not be)."""
    box = {}

    def work():
        try:
            t = None if timeout_s is None else (min(CONNECT_TIMEOUT_S, timeout_s), timeout_s)
            with requests.request(method, url, timeout=t, stream=True, **kw) as r:
                if sink is not None and r.status_code == 200:
                    for chunk in r.iter_content(65536):
                        sink(chunk)
                    body = b""
                else:
                    body = r.content
                box["resp"] = Response(r.status_code, r.headers, body)
        except BaseException as e:  # noqa: BLE001 - re-raised in the caller
            box["err"] = e

    th = threading.Thread(target=work, daemon=True)
    th.start()
    th.join(timeout_s)
    if th.is_alive():
        raise _AttemptTimeout(f"no complete response within {timeout_s:.2f} s")
    if "err" in box:
        raise box["err"]
    return box["resp"]


def _delay(attempt):
    if MUTANT == "TIGHT_LOOP":
        return 0.0
    if MUTANT == "FIXED_BACKOFF":  # the same capped exponential schedule, without jitter
        return min(MAX_DELAY_S, BASE_DELAY_S * 2 ** attempt)
    # full jitter over [floor, cap(base * 2^k)]: uniform, no point mass at the floor
    return random.uniform(MIN_DELAY_S, max(MIN_DELAY_S, min(MAX_DELAY_S, BASE_DELAY_S * 2 ** attempt)))


def call(method, url, deadline, idempotent, sink_factory=None, headers_fn=None, accept=(200, 201, 202, 204), **kw):
    """Performs the request with the reference policy; returns the final
    Response (status in `accept` or a non-retryable status; .attempts is set),
    or raises _GiveUp. sink_factory(attempt) returns a fresh body sink per
    attempt (an abandoned attempt never writes into a later one);
    headers_fn(attempt) returns the headers of that attempt."""
    attempt = 0
    last = None
    while True:
        if headers_fn is not None:
            kw["headers"] = headers_fn(attempt)
        remaining = None if MUTANT == "NO_TIMEOUT" else deadline - time.monotonic()
        if remaining is not None and remaining < MIN_ATTEMPT_S:
            raise _GiveUp(f"deadline reached: {last}")
        timeout = None if remaining is None else min(ATTEMPT_TIMEOUT_S, remaining)
        retry_after = None
        try:
            sink = sink_factory(attempt) if sink_factory is not None else None
            r = _one_attempt(method, url, timeout, sink=sink, **kw)
            r.attempts = attempt + 1
            if r.status in accept or r.status not in RETRY_STATUSES:
                return r
            last = f"HTTP {r.status}"
            retry_after = None if MUTANT == "IGNORE_RETRY_AFTER" else _retry_after_s(r.headers)
        except (requests.exceptions.RequestException, _AttemptTimeout, OSError) as e:
            last = repr(e)
            may_have_been_processed = isinstance(e, _AttemptTimeout) or _sent_maybe(e)
            if may_have_been_processed and not idempotent and MUTANT != "UNSAFE_POST_RETRY":
                raise _GiveUp(f"outcome unknown, not retried: {last}") from e
        if attempt + 1 >= MAX_ATTEMPTS and MUTANT != "TIGHT_LOOP":
            raise _GiveUp(f"{MAX_ATTEMPTS} attempts failed: {last}")
        d = _delay(attempt)
        if retry_after is not None:
            d = max(d, retry_after)
        if MUTANT != "NO_TIMEOUT" and time.monotonic() + d > deadline - MIN_ATTEMPT_S:
            raise _GiveUp(f"no time left to retry after {last}")
        time.sleep(d)
        attempt += 1


def deadline_in(budget_s):
    return time.monotonic() + budget_s
# --- end of reference HTTP policy ---------------------------------------------

from urllib.parse import quote


class SubscriptionError(Exception):
    pass


def cancel_subscription(base_url: str, subscription_id: str) -> None:
    dl = deadline_in(9.5)
    try:
        r = call("DELETE", f"{base_url}/v1/subscriptions/{quote(subscription_id, safe='')}", dl, idempotent=True)
    except _GiveUp as e:
        raise SubscriptionError(str(e)) from e
    if r.status == 200:
        return None
    if r.status == 404 and r.attempts > 1:
        return None  # an earlier attempt may have canceled it
    raise SubscriptionError(f"HTTP {r.status}")
